def insert(items, index, value):
    if not 0 <= index <= len(items):
        raise IndexError('invalid insert index')
    items.append(None)
    for i in range(len(items) - 1, index, -1):
        items[i] = items[i - 1]
    items[index] = value

def delete(items, index):
    if not 0 <= index < len(items):
        raise IndexError('invalid delete index')
    removed = items[index]
    for i in range(index, len(items) - 1):
        items[i] = items[i + 1]
    items.pop()
    return removed

