print(first_index(values, 2))
print(first_index(values, 3))

class HashTable:
    def __init__(self, capacity):
        self.table = [None] * capacity

    def insert(self, key):
        start = key % len(self.table)
        for step in range(len(self.table)):
            index = (start + step) % len(self.table)
            if self.table[index] in (None, key):
                self.table[index] = key
                return index
        raise OverflowError('hash table full')

    def find(self, key):
        start = key % len(self.table)
        for step in range(len(self.table)):
            index = (start + step) % len(self.table)
            if self.table[index] is None:
                return -1
            if self.table[index] == key:
                return index
        return -1

