def quick_sort(values):
    if len(values) <= 1:
        return values[:]
    pivot = values[len(values) // 2]
    less = [value for value in values if value < pivot]
    equal = [value for value in values if value == pivot]
    greater = [value for value in values if value > pivot]
    return quick_sort(less) + equal + quick_sort(greater)

print(quick_sort([5, 1, 3, 3, 9, 2, 5]))

def merge_sort(records):
    if len(records) <= 1:
        return records[:]
    middle = len(records) // 2
    left = merge_sort(records[:middle])
    right = merge_sort(records[middle:])
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i][0] <= right[j][0]:
            result.append(left[i]); i += 1
        else:
            result.append(right[j]); j += 1
    return result + left[i:] + right[j:]

records = [(2, 'A'), (1, 'B'), (2, 'C'), (1, 'D')]
print(merge_sort(records))
